-- ----------------------------
-- Table structure for `lt_ssc_static_val`
-- ----------------------------
DROP TABLE IF EXISTS `lt_ssc_static_val`;
CREATE TABLE `lt_ssc_static_val` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `val` varchar(120) DEFAULT NULL COMMENT '值',
  `codes_hz` int(11) DEFAULT NULL COMMENT '号码和值',
  `name` varchar(64) DEFAULT NULL COMMENT '名字',
  `status` tinyint(1) DEFAULT '1' COMMENT '是否显示0不显示1显示',
  `type` tinyint(1) DEFAULT '1' COMMENT '类型：1和值2号码类型[例如:双双重、三重]3三字现带双重4四字现带双重5四字现不带双重',
  `static_nums` int(11) DEFAULT '472' COMMENT '统计期数',
  `count` int(11) DEFAULT NULL COMMENT '组数',
  `created_at` int(11) DEFAULT NULL COMMENT '创建时间',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `type_2` tinyint(1) DEFAULT '0' COMMENT '是否双重',
  `type_22` tinyint(1) DEFAULT '0' COMMENT '是否双双重',
  `type_3` tinyint(1) DEFAULT '0' COMMENT '是否三重',
  `type_4` tinyint(1) DEFAULT '0' COMMENT '是否四重',
  `type_2b` tinyint(1) DEFAULT '0' COMMENT '是否两兄弟',
  `type_3b` tinyint(1) DEFAULT '0' COMMENT '是否三兄弟',
  `type_4b` tinyint(1) DEFAULT '0' COMMENT '是否四兄弟',
  `type_4d` tinyint(1) DEFAULT '0' COMMENT '是否四单',
  `type_4s` tinyint(1) DEFAULT '0' COMMENT '是否四双',
  `type_log` tinyint(1) DEFAULT '0' COMMENT '是否对数',
  `type_4ds` tinyint(1) DEFAULT '0' COMMENT '是否四单四双',
  PRIMARY KEY (`id`),
  KEY `val` (`val`),
  KEY `status` (`status`),
  KEY `type` (`type`),
  KEY `val, type` (`val`,`type`)
) ENGINE=MyISAM AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8 COMMENT='四定统计基本表';

